using System;using UnityEngine;using NUnit.Framework;using LighthouseKeepers.Core;
namespace LighthouseKeepers.Net.Tests {
 public sealed class CampaignOrderTests {
  static Type T(string n)=>Type.GetType("LighthouseKeepers.WatchDemo."+n+", Assembly-CSharp",true);
  static object Call(object o,string n,params object[] a)=>o.GetType().GetMethod(n).Invoke(o,a);
  static V Get<V>(object o,string n)=>(V)o.GetType().GetProperty(n).GetValue(o);
  static object New(int day){var c=Resources.Load("M3Campaign");return Activator.CreateInstance(T("WatchState"),c.GetType().GetField("nights").GetValue(c),day,Resources.Load("S4Tuning"),Resources.Load("S4M2Tuning"),Resources.Load("ImmersionTuning"));}
  static string Step(object s){var d=Get<object>(s,"Director");Call(d,"Tick",0f,1,new Vector3(0,12,0),0,Vector3.zero,true);return Get<object>(d,"First").ToString();}
  static void Start(object s){for(int i=0;i<100;i++)Call(s,"PourFuel",.1f);for(int i=0;i<3;i++){Call(s,"PrimeEngine");Call(s,"Tick",.4d);}Call(s,"SetChoke",true);for(int i=0;i<3;i++){Call(s,"StarterPulled");Call(s,"Tick",.4d);}Call(s,"SetChoke",false);}
  [Test]public void GeneratorThenPipeThenRadioRegardlessOfPlayersFloor(){var s=New(2);Assert.AreEqual("Fuel",Step(s));Start(s);StringAssert.StartsWith("Bolt",Step(s));Call(s,"CompleteRepair");Assert.AreEqual("RadioOn",Step(s));Call(s,"SetCircuit",2,true);Assert.AreEqual("RadioPower",Step(s));Call(s,"SetCircuit",1,false);Assert.False(Get<bool>(s,"BeaconShining"));Assert.AreEqual("RadioPower",Step(s),"Radio clearance must not require the already aimed beacon.");}
  [Test]public void LocalRadioCodeNeverSendsPartnerToHouseTelegram(){var s=New(1);Call(s,"SetKeeperCount",2);Call(s,"CompleteRepair");var d=Get<object>(s,"Director");Call(d,"Tick",0f,1,Vector3.zero,2,Vector3.up*12,true);Assert.AreEqual("RadioPower",Get<object>(d,"First").ToString());Assert.AreEqual("RadioPower",Get<object>(d,"Second").ToString());}
  [Test]public void NightOneCannotFinishWithOnlyPipeAndNoRadioOrWheel(){var s=New(1);Call(s,"CompleteRepair");Call(s,"Tick",450d);Assert.False(Get<bool>(s,"Complete"));Assert.False(Get<bool>(s,"Failed"));Assert.AreEqual("RadioPower",Step(s));var ships=Get<object>(s,"Ships");Assert.False(Get<bool>(ships,"ClearanceGranted"));Assert.AreEqual(-1,Get<int>(s,"AimingShip"));}
  [Test]public void ActualRadioTransmissionReleasesShipsAndRetryRestoresHold(){var s=New(1);Call(s,"CompleteRepair");var r=Get<object>(s,"Radio");Call(r,"ToggleMain");var p=r.GetType().GetField("Program").GetValue(r);Call(r,"Tune",(float)p.GetType().GetField("targetMHz").GetValue(p));Call(s,"Tick",3d);for(int i=0;i<Get<int>(r,"CodeLength");i++)Call(r,"PressCode",Call(r,"CodeSymbol",i));Call(r,"SetMicrophone",true,true);Call(s,"Tick",5d);Call(s,"Tick",.1d);Assert.True(Get<bool>(r,"Completed"));Assert.True(Get<bool>(Get<object>(s,"Ships"),"ClearanceGranted"));Assert.False(Get<bool>(s,"Complete"));var g=New(1);Call(g,"SetRemoteReplica",true);Assert.True((bool)Call(g,"ApplyRemote",Call(s,"Capture",0f)));Assert.True(Get<bool>(Get<object>(g,"Ships"),"ClearanceGranted"));Call(s,"Retry");Assert.True((bool)Call(g,"ApplyRemote",Call(s,"Capture",0f)));Assert.False(Get<bool>(Get<object>(g,"Ships"),"ClearanceGranted"));}
 }
}
